-- 0140_auth_tokens_current_connector_credential_idx — Jira RT-1362 S2 (follows 0139), `[GATED: migration]` (RT-1362
-- comments 19102 and 19107). At most ONE CURRENT unrevoked connector credential per registration: the 0021
-- one-unrevoked-credential rule, narrowed to credentials with no pending marker (`pending_rotation_request_id IS
-- NULL`). With 0141 (at most one PENDING) it is the overlap rule that replaces `uq_auth_tokens_active_connector_credential`
-- once a later PR drops that index; until then both coexist and the 0021 one stays the stricter rule. Expiry is
-- deliberately not in the predicate (now() is STABLE, not IMMUTABLE; the 0021 note).
-- A dedicated single-statement CONCURRENTLY migration (precedents 0036, 0048, 0117, 0126): auth_tokens is read on
-- every bearer lookup, and the build takes only SHARE UPDATE EXCLUSIVE. The rows it covers already satisfy it (the
-- 0021 index allows at most one unrevoked connector credential per registration). Deliberately NO `IF NOT EXISTS`
-- (see 0117): an interrupted build fails the retry until the INVALID index is dropped: fail closed.
CREATE UNIQUE INDEX CONCURRENTLY uq_auth_tokens_current_connector_credential ON auth_tokens (connector_registration_id) WHERE scope = 'connector' AND revoked_at IS NULL AND pending_rotation_request_id IS NULL;
